    const gia = prese.findIndex((presa2) => presa2.entity === modulo.entity);
    if (gia >= 0 && gia !== indice2) {
      if (errore)
        errore.textContent = t(
          "Questa entità è già configurata.",
          "This entity is already configured."
        );
      return;
    }
    if (errore) errore.textContent = "";
    const elenco = prese.slice();
    const voce = {
      ...indice2 === null ? {} : elenco[indice2],
      name: modulo.name,
      entity: modulo.entity,
      icon: modulo.icon,
      room_id: modulo.room_id,
      power: modulo.power
    };
    const entitaPrima = indice2 === null ? "" : clean13(elenco[indice2]?.entity);
    if (entitaPrima && entitaPrima !== clean13(voce.entity)) segnaSoloLettura(entitaPrima, false);
    if (indice2 === null) elenco.push(voce);
